mapper.select:
select `prod`.`id` as `prodId`, `prod`.`prod_number` as `prodNumber`, `prod`.`prod_name` as `prodName`, `prod`.`prod_model` as `prodModel`, `category`.`item_label` as `prodCategoryName`, `category`.`item_level` as `prodCategoryCode`, `brand`.`item_level` as `prodBrandCode`, `brand`.`item_label` as `prodBrandName`, `prod`.`remark` as `remark`, `prod`.`prod_icon` as `prodIcon`, `prod`.`prod_pic` as `prodPic` from `iot_md_product` `prod` left join `iot_sys_dict_item` `category` on `prod`.`prod_category_id` = `category`.`id` left join `iot_sys_dict_item` `brand` on `prod`.`prod_brand_id` = `brand`.`id` where 1=1
and `prod`.`id` = #{productId}
and `prod`.`prod_name` like concat('%',#{param.productName},'%')
and `category`.`item_label` like concat('%',#{param.productCategoryName},'%')
#{item}
and `brand`.`item_level` = #{param.productBrandCode}

select `item`.`id` as `itemId`, `item`.`item_label` as `itemLabel`, `item`.`item_level` as `itemCode`, `item`.`item_parent_id` as `itemParentId` from `iot_sys_dict_item` `item` where `item`.`dict_id` = #{dictTypeId}
and `item`.`item_label` like concat(#{itemQueryParam.itemLabel}, '%')
and `item`.`item_level` like concat(#{itemQueryParam.itemLevel}, '%')
